+
+import { Router, Request, Response } from 'express';
+import { z } from 'zod';
+import { ServiceListing, IListingsRepo, IProfilesRepo } from '../../shared/types';
+import {
+  authenticateToken,
+  optionalAuth,
+  AuthenticatedRequest,
+  listingCreateLimiter,
+  sanitizeAll,
