+
+/**
+ * Refresh auth token
+ */
+export function refreshAuthToken(oldToken: string): string | null {
+  const auth = verifyAuthToken(oldToken);
+  if (!auth) {
+    return null;
+  }
+
+  // Generate new token with same profile/session
+  return generateAuthToken(auth.profileId, auth.sessionId);
