+
+  /**
+   * Get connection count
+   */
+  getConnectionCount(): number {
+    return this.clients.size;
+  }
+
+  /**
+   * Get stats
+   */
+  getStats(): {
+    totalConnections: number;
+    connectionsByProfile: Map<string, number>;
+    averageSessionDuration: number;
+    totalMessages: number;
+  } {
+    const now = Date.now();
